    rules = list(app.url_map.iter_rules())
    if not rules:
        click.echo("No routes were registered.")
        return

    ignored_methods = set(())

    if app.config["TRAP_HTTP_EXCEPTIONS"]:
        ignored_methods |= {"HEAD", "OPTIONS"}

    if app.config["PROVIDE_AUTOMATIC_OPTIONS"]:
        ignored_methods |= {"OPTIONS"}

    server_name = app.config.get("SERVER_NAME", "")

    rows = []
    for rule in rules:
        methods = [v for v in rule.methods if v not in ignored_methods]
        methods.sort()

        # Determine the domain for this rule
        if rule.subdomain:
            if server_name:
                domain = f"{rule.subdomain}.{server_name}"
            else:
                domain = rule.subdomain
        else:
            domain = server_name or ""

        rows.append((domain, rule.endpoint, ", ".join(methods), rule.rule))

    # Print the table using tabulate
    headers = ("Domain", "Endpoint", "Methods", "Rule")
    table = tabulate(rows, headers, tablefmt="plain")
    click.echo(table)
